/*
TheGrayCuber
2025.12.10

This is a visualization of Fermat's Little Theorem, applied to complex numbers.
For each frame, we display all values congruent to the 'current value' over the modulus.
We then move to the next frame by multiplying the current value by our multplier.
This works best if the modulus is prime: https://thegraycuber.github.io/quadratic

This skecth is a supplement to my video on the topic: https://youtu.be/tcwFd8JbzQY
*/

// try changing these 3 values
var modulus = [0,11]; // 11i
var multiplier = [3,1]; // 3+i
var startPoint = [2,-4]; // 2-4i



function complexMult(a, b){
	return [a[0]*b[0] - a[1]*b[1], a[1]*b[0] + a[0]*b[1]];
}

function complexStr(a){
	return str(a[0]) + ';' + str(a[1]);
}

function roundedDivision(a, b){
	let bNorm = b[0]**2 + b[1]**2;
	let unscaled = complexMult(a,[b[0],-b[1]]);
	return [round(unscaled[0]/bNorm),round(unscaled[1]/bNorm)];
}

function getRepresentative(a){
	let roundedQuotient = roundedDivision(a,modulus);
	let nearestMultiple = complexMult(modulus,roundedQuotient);
	return [a[0] - nearestMultiple[0], a[1] - nearestMultiple[1]];
}

function draw() {

	translate(origin.x, origin.y);
	scale(scalar, -scalar);

	background(backgroundColor);

	currentValue = getRepresentative(complexMult(currentValue,multiplier));
	let currentClass = equivalenceClasses[complexStr(currentValue)];

	for (let z of currentClass){
		rect(z[0],z[1],1);
	}	
}


var origin, scalar, currentValue, backgroundColor;
var equivalenceClasses = {};

function setup() {
	createCanvas(windowWidth, windowHeight);
	rectMode(CENTER);
	frameRate(15);

	backgroundColor = color('#2b1752');
	background(backgroundColor);
	backgroundColor.setAlpha(5);

	noStroke();
	fill('#bc7ff5');

	origin = createVector(width/2, height/2);
	scalar = height/36;


	let extremes = [floor(width/(2*scalar))+2,floor(height/(2*scalar))+2];

	for (let re = -extremes[0]; re <= extremes[0]; re++){
		for (let im = -extremes[1]; im <= extremes[1]; im++){

			let rep = complexStr(getRepresentative([re,im]));
			if (!(rep in equivalenceClasses)){
				Object.defineProperty(equivalenceClasses,rep,{value:[]});
			}
			equivalenceClasses[rep].push([re,im]);
		}
	}

	currentValue = [...startPoint];
}
